using Ashlar.Core.Domain.Bricks;
using Ashlar.Core.Domain.Execution;

namespace Ashlar.Samples.Dogfood.Locks;

public sealed class DoorLockTransitionBrick : DomainBrick
{
    public DoorLockTransitionBrick()
    {
        Id = "door-lock-transition";
        Name = "Door Lock Transition";
        Description = "Computes the next state of a three-state door lock for a given event.";
        Interface = new BrickInterface
        {
            Inputs =
            [
                new BrickInputDefinition("state", "string", "current state"),
                new BrickInputDefinition("trigger", "string", "trigger")
            ],
            Outputs =
            [
                new BrickOutputDefinition("nextState", "string", "next state"),
                new BrickOutputDefinition("accepted", "bool", "accepted")
            ]
        };
    }

    public override Task<BrickOutput> ExecuteAsync(
        BrickInput input,
        ImplementationType implementation,
        IExecutionContext context,
        CancellationToken cancellationToken = default)
    {
        var state = input.Get<string>("state", string.Empty) ?? string.Empty;
        var trigger = input.Get<string>("trigger", string.Empty) ?? string.Empty;

        var nextState = state;
        var accepted = false;

        if (state == "locked" && trigger == "unlock")
        {
            nextState = "unlocked";
            accepted = true;
        }
        else if (state == "unlocked" && trigger == "lock")
        {
            nextState = "locked";
            accepted = true;
        }
        else if (state == "unlocked" && trigger == "open")
        {
            nextState = "open";
            accepted = true;
        }
        else if (state == "open" && trigger == "close")
        {
            nextState = "unlocked";
            accepted = true;
        }

        var output = new BrickOutput();
        output.Set("nextState", nextState);
        output.Set("accepted", accepted);

        return Task.FromResult(output);
    }
}
